1	//! What the experimental TypeScript checker backend hands back, and how it merges over the structural result.
2	//!
3	//! The backend (`caliper-docgen-semantic`) owns the process, the protocol and the checker walk; this module owns only
4	//! the result shape and the merge rules of `docs/type-checker-integration.md`, so `crates/core` stays free of I/O.
5	
6	use std::collections::BTreeMap;
7	use std::hash::{Hash, Hasher};
8	use std::sync::{Arc, Mutex};
9	
10	use camino::Utf8PathBuf;
11	use rustc_hash::{FxHashMap, FxHasher};
12	
13	mod order;
14	
15	use crate::types::collected::ComponentExport;
16	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
17	use crate::types::output::{
18	    ComponentEntry, ExtractionOutput, OpaqueDetail, OpaqueReason, ParsedProp, PropParent, PropType, TRUNCATED_KIND,
19	};
20	
21	/// The type of a name the checker could not resolve (an import that does not resolve, a name declared nowhere), which
22	/// the checker answers with its error type: an `any` that is not a written `any`. It is `opaque` with the reason
23	/// `unresolvableImport`, so the prop carries `degradedBy`, and `written` is the name as the source writes it, which is
24	/// also what the reason names (the checker does not say which module specifier was behind it).
25	pub fn unresolved_type(written: impl Into<String>) -> PropType {
26	    let written = written.into();
27	    OpaqueDetail::new(written.clone(), OpaqueReason::UnresolvableImport { specifier: written })
28	}
29	
30	/// A type the checker holds that PropType has no shape for: a conditional or indexed access type it could not resolve
31	/// (its parameters are still open), `keyof T`. It is `opaque` with `reason`, so the prop carries `degradedBy`, and
32	/// `raw` is how the checker prints it.
33	pub fn degraded_type(raw: impl Into<String>, reason: OpaqueReason) -> PropType {
34	    OpaqueDetail::new(raw, reason)
35	}
36	
37	/// One prop as the checker reports it.
38	#[derive(Debug, Clone, PartialEq)]
39	pub struct SemanticProp {
40	    /// The prop's name as written in the props type.
41	    pub name: String,
42	    /// The type the checker computed for it, in the same shape the structural resolver produces.
43	    pub prop_type: PropType,
44	    /// Whether the checker found the prop non-optional.
45	    pub required: bool,
46	    /// The prop's JSDoc description, empty when it has none; the merge then keeps the structural description.
47	    pub description: String,
48	    /// The prop's JSDoc tags (`@deprecated`, `@since`, `@default`), each by name with the text the checker renders, empty
49	    /// when it has none; the merge then keeps the structural tags, as for `description`. `@types/react`'s props are not
50	    /// asked for theirs.
51	    pub tags: BTreeMap<String, String>,
52	    /// The interface that declares the prop, as react-docgen-typescript states it: the parent of its first declaration
53	    /// when that is an interface, with the file it is in. `None` for a prop declared in a type literal or with no
54	    /// declaration. It replaces the structural `parent`, `None` included.
55	    pub parent: Option<PropParent>,
56	    /// The interface of each declaration that is in one, in the checker's order: two when an intersection or a merged
57	    /// interface declares the prop twice.
58	    pub declarations: Vec<PropParent>,
59	    /// Declared by `@types/react` (`children`, `aria-*`, handlers, `className`): not the component's own prop.
60	    pub react_declared: bool,
61	}
62	
63	impl SemanticProp {
64	    fn structural_hash(&self) -> u64 {
65	        let mut hasher = FxHasher::default();
66	        self.name.hash(&mut hasher);
67	        self.required.hash(&mut hasher);
68	        self.react_declared.hash(&mut hasher);
69	        self.description.hash(&mut hasher);
70	        self.tags.hash(&mut hasher);
71	        for parent in self.parent.iter().chain(&self.declarations) {
72	            parent.name.hash(&mut hasher);
73	            parent.file_name.hash(&mut hasher);
74	        }
75	        self.prop_type.structural_hash(&mut hasher);
76	        hasher.finish()
77	    }
78	}
79	
80	/// Shares identical props between components, as the structural resolver does: a design system's components repeat
81	/// the same few hundred props, and Chakra's 600 components would otherwise hold 470,000 copies.
82	#[derive(Debug, Default)]
83	pub struct PropInterner {
84	    by_hash: Mutex<FxHashMap<u64, Vec<Arc<SemanticProp>>>>,
85	}
86	
87	impl PropInterner {
88	    /// The one shared copy of `prop`: an equal prop interned earlier, or `prop` itself the first time. If the internal
89	    /// lock is poisoned it returns `prop` unshared rather than failing.
90	    pub fn share(&self, prop: SemanticProp) -> Arc<SemanticProp> {
91	        let hash = prop.structural_hash();
92	        let Ok(mut by_hash) = self.by_hash.lock() else { return Arc::new(prop) };
93	        let bucket = by_hash.entry(hash).or_default();
94	        if let Some(existing) = bucket.iter().find(|existing| ***existing == prop) {
95	            return existing.clone();
96	        }
97	        let shared = Arc::new(prop);
98	        bucket.push(shared.clone());
99	        shared
100	    }
101	}
102	
103	/// One component the checker answered for.
104	#[derive(Debug, Clone, PartialEq)]
105	pub struct SemanticComponent {
106	    /// The output key of the [`SemanticTarget`] this answers: the entry to merge into.
107	    pub key: String,
108	    /// Declared props in declaration order, with the `@types/react` ones the request asked for.
109	    pub props: Vec<Arc<SemanticProp>>,
110	    /// The `@types/react` types the props type is made of (`RefAttributes`, `HTMLAttributes` under an `Omit`), by
111	    /// name, in the order the props type names them: what the checker leaves to the inheritance layers. `Some` replaces
112	    /// the structural `composes`, which also lists the types the structural pass could not follow and the checker did,
113	    /// and `Some` of an empty list says the props type is made of none. `None` says the checker could not tell (a type
114	    /// it cannot read the bases of), and the structural `composes` stays.
115	    pub composes: Option<Vec<String>>,
116	}
117	
118	/// A component the backend left to the structural result, and why.
119	#[derive(Debug, Clone, PartialEq, Eq)]
120	pub struct SemanticFallback {
121	    /// The output key of the [`SemanticTarget`] this answers.
122	    pub key: String,
123	    /// Why the checker did not answer, for example that the component is not exported by its module. The merge groups
124	    /// components by this text into one warning.
125	    pub reason: String,
126	}
127	
128	/// The backend's answer for a run. A backend that could not start returns no components and one diagnostic, never an
129	/// error: the structural result is always a complete answer on its own.
130	#[derive(Debug, Clone, Default, PartialEq)]
131	pub struct SemanticOutcome {
132	    /// The components the checker answered for; each replaces the props of the structural entry it names.
133	    pub components: Vec<SemanticComponent>,
134	    /// The requested components the checker left to the structural result, each with its reason.
135	    pub fallbacks: Vec<SemanticFallback>,
136	    /// What the backend itself reports (it could not start, it timed out); merged into the output's diagnostics.
137	    pub diagnostics: Vec<Diagnostic>,
138	}
139	
140	/// A component the checker may be asked about.
141	#[derive(Debug, Clone, PartialEq, Eq)]
142	pub struct SemanticTarget {
143	    /// The component's output key. Its answer, or its fallback, carries it back, and the merge finds the entry by it:
144	    /// never by file and display name, which two components can share.
145	    pub key: String,
146	    /// The file that declares the component.
147	    pub file_path: Utf8PathBuf,
148	    /// The component's display name, for messages; the checker does not look the component up by it.
149	    pub display_name: String,
150	    /// How the module exports the component ([`ComponentEntry::exports`]): the checker asks for it by exactly these.
151	    /// It answers only for exported components and reports the rest as fallbacks.
152	    pub exports: Vec<ComponentExport>,
153	    /// Props the structural pass already has a description for. The checker is not asked for those: it is 65% of
154	    /// the requests on Mantine, and the merge keeps the structural description when the checker's is empty.
155	    pub described: rustc_hash::FxHashSet<String>,
156	    /// Which props `@types/react` declares the checker reports: `None` for all of them, else only these names. The
157	    /// session decides from `htmlAttributes` (`react_types::react_props_wanted`); the checker never filters by itself.
158	    pub react_wanted: Option<rustc_hash::FxHashSet<String>>,
159	}
160	
161	/// A checker that answers for components as they are asked about, for a long-lived session.
162	///
163	/// `request` never blocks: it queues the targets and returns the receiver that yields the outcome once the checker
164	/// has it, so a caller can wait a bounded time and take the structural answer when the checker is slower.
165	pub trait SemanticProvider: Send + Sync {
166	    /// Queues `targets` for the checker and returns at once with the receiver that will yield their
167	    /// [`SemanticOutcome`]. Someone is waiting for it: the request is [`Priority::Interactive`].
168	    fn request(&self, targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome>;
169	
170	    /// Queues `targets` at `priority` and returns at once; `delivery` receives the outcome. A checker that answers one
171	    /// request at a time answers an interactive request before a background one, and reads `priority` again when it
172	    /// picks the next, since a caller that joins a background request may raise it. The default ignores the priority
173	    /// and waits for [`Self::request`]'s receiver on a thread of its own.
174	    fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
175	        drop(priority);
176	        let receiver = self.request(targets);
177	        let delivery = Arc::new(Mutex::new(Some(delivery)));
178	        let take =
179	            |slot: &Mutex<Option<Delivery>>| slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
180	        let waiter = delivery.clone();
181	        let waiting = std::thread::Builder::new().name("caliper-checker-answer".to_string()).spawn(move || {
182	            let outcome = receiver.recv().ok();
183	            if let Some(delivery) = take(&waiter) {
184	                delivery.deliver(outcome);
185	            }
186	        });
187	        if let Err(error) = waiting
188	            && let Some(delivery) = take(&delivery)
189	        {
190	            delivery.deliver(Some(SemanticOutcome::unavailable(format!(
191	                "could not start a thread to wait for it: {error}"
192	            ))));
193	        }
194	    }
195	
196	    /// Tells the checker that files changed on disk, before any request that may read them is queued. A checker that
197	    /// keeps what it read (a warm `tsc` holding a snapshot, ADR 0026) reads them again; one that reads every file
198	    /// afresh for each request needs nothing, which is the default.
199	    fn changed(&self, _change: SourceChange) {}
200	}
201	
202	/// Who waits for a request to the checker, which decides what a busy checker answers first.
203	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
204	pub enum Priority {
205	    /// A component someone is looking at now: a story that was opened.
206	    Interactive,
207	    /// Work nobody waits for yet: a warm-up, a fill, a prefetch.
208	    Background,
209	}
210	
211	/// The priority of one queued request, shared between the caller and the checker so that a later caller can raise it
212	/// ([`SharedPriority::raise`]) while the request waits. Clones share one priority.
213	#[derive(Debug, Clone)]
214	pub struct SharedPriority(Arc<std::sync::atomic::AtomicBool>);
215	
216	impl SharedPriority {
217	    /// A priority that starts at `priority`.
218	    pub fn new(priority: Priority) -> Self {
219	        Self(Arc::new(std::sync::atomic::AtomicBool::new(priority == Priority::Interactive)))
220	    }
221	
222	    /// The priority now.
223	    pub fn get(&self) -> Priority {
224	        match self.0.load(std::sync::atomic::Ordering::Acquire) {
225	            true => Priority::Interactive,
226	            false => Priority::Background,
227	        }
228	    }
229	
230	    /// Makes the request interactive: someone is now waiting for it.
231	    pub fn raise(&self) {
232	        self.0.store(true, std::sync::atomic::Ordering::Release);
233	    }
234	}
235	
236	/// Where the outcome of a request made with [`SemanticProvider::request_at`] goes. It is used once: with the outcome,
237	/// or with `None` when the checker stopped without answering. Dropping it unused counts as `None`, so a caller is
238	/// told even when the request is lost (a worker that stopped, a thread that could not start).
239	pub struct Delivery(Option<Box<dyn FnOnce(Option<SemanticOutcome>) + Send>>);
240	
241	impl Delivery {
242	    /// A delivery that hands the outcome to `receive`.
243	    pub fn new(receive: impl FnOnce(Option<SemanticOutcome>) + Send + 'static) -> Self {
244	        Self(Some(Box::new(receive)))
245	    }
246	
247	    /// Hands over the outcome, or `None` for a checker that stopped without answering.
248	    pub fn deliver(mut self, outcome: Option<SemanticOutcome>) {
249	        if let Some(receive) = self.0.take() {
250	            receive(outcome);
251	        }
252	    }
253	}
254	
255	impl Drop for Delivery {
256	    fn drop(&mut self) {
257	        if let Some(receive) = self.0.take() {
258	            receive(None);
259	        }
260	    }
261	}
262	
263	impl std::fmt::Debug for Delivery {
264	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
265	        f.debug_struct("Delivery").field("delivered", &self.0.is_none()).finish()
266	    }
267	}
268	
269	/// What changed on disk, as a session tells its checker ([`SemanticProvider::changed`]).
270	#[derive(Debug, Clone, PartialEq, Eq)]
271	pub enum SourceChange {
272	    /// These files were edited, created or deleted.
273	    Files(Vec<Utf8PathBuf>),
274	    /// Anything may have changed: the session extracted everything again (a resolution config changed, or it started).
275	    Everything,
276	}
277	
278	impl SemanticOutcome {
279	    /// An outcome for a backend that did nothing: the structural result stands, for this reason.
280	    pub fn unavailable(reason: impl Into<String>) -> Self {
281	        let diagnostic = Diagnostic::new(
282	            DiagnosticSeverity::Warning,
283	            DiagnosticCode::SemanticBackend,
284	            format!("TypeScript checker backend unavailable: {}", reason.into()),
285	        )
286	        .with_help(
287	            "The structural result is used instead. Install `typescript@beta` (7.1) or `tsrs`, or pass `--tsc-path`.",
288	        );
289	        Self { diagnostics: vec![diagnostic], ..Self::default() }
290	    }
291	}
292	
293	/// Replaces `entry`'s props and `composes` with the checker's, keeping what only the structural pass has (a default
294	/// value, and a description or tags when the checker has none). A prop whose type the checker could not read keeps its
295	/// structural type, marked (see [`merge_semantic_props`]). `shared` interns identical props across the components of
296	/// one merge. Returns how many props kept their structural type that way.
297	pub fn apply_semantic_props(
298	    entry: &mut ComponentEntry,
299	    semantic: &SemanticComponent,
300	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
301	) -> usize {
302	    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers.
303	    let own = semantic.props.iter().filter(|prop| !prop.react_declared);
304	    replace_props(entry, own, semantic.composes.as_deref(), Unanswered::Drop, shared).unread
305	}
306	
307	/// How a merge went for one component.
308	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
309	pub struct MergedProps {
310	    /// Structural props the checker did not return, kept as the structural pass resolved them.
311	    pub kept: usize,
312	    /// Props the checker returned with a type it could not read (an `opaque` part: an import that does not resolve, a
313	    /// conditional type it left open), where the structural pass read the type in full. They keep the structural type,
314	    /// and their `degradedBy` also lists what the checker could not read.
315	    pub unread: usize,
316	}
317	
318	/// Merges the checker's `props` into `entry` by name: the checker's type, optionality, description, tags, `parent` and
319	/// `declarations` win where both have a prop, and every structural prop the checker did not return stays as the
320	/// structural pass resolved it. `composes` replaces the entry's when the checker decided it, and an undecided one leaves
321	/// the structural `composes` ([`SemanticComponent::composes`]). A prop whose checker
322	/// type holds an `opaque` part, where the structural type holds none, keeps the structural type and adds the checker's
323	/// reasons to its `degradedBy`: the checker's answer there is a placeholder, and the structural one is not confirmed,
324	/// so it is marked. A type the checker only cut at a limit (`truncated`) is still its answer.
325	pub fn merge_semantic_props<'a>(
326	    entry: &mut ComponentEntry,
327	    props: impl Iterator<Item = &'a Arc<SemanticProp>>,
328	    composes: Option<&[String]>,
329	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
330	) -> MergedProps {
331	    replace_props(entry, props, composes, Unanswered::Keep, shared)
332	}
333	
334	/// The kinds of what the checker could not read in `checker`, when the structural type `structural` read everything:
335	/// then the structural type is kept and marked with them. Empty when the checker's type is its answer.
336	fn unread_by_checker(checker: &PropType, structural: &PropType) -> Vec<&'static str> {
337	    let unread: Vec<&'static str> = checker.degraded_by().into_iter().filter(|kind| *kind != TRUNCATED_KIND).collect();
338	    if unread.is_empty() || structural.degraded_by().iter().any(|kind| *kind != TRUNCATED_KIND) {
339	        return Vec::new();
340	    }
341	    unread
342	}
343	
344	/// The one diagnostic for the props of `affects` that kept their structural type because the checker could not read it
345	/// ([`MergedProps::unread`]); each such prop says why in its `degradedBy`.
346	pub(crate) fn unread_diagnostic(props: usize, affects: Vec<String>) -> Diagnostic {
347	    let mut diagnostic = Diagnostic::new(
348	        DiagnosticSeverity::Info,
349	        DiagnosticCode::SemanticBackend,
350	        format!(
351	            "{props} prop(s) of {} component(s) keep their structural type: the TypeScript checker could not read it, \
352	             and their degradedBy says what it could not read",
353	            affects.len()
354	        ),
355	    );
356	    diagnostic.affects = affects;
357	    diagnostic
358	}
359	
360	/// What a merge does with a structural prop the checker did not return.
361	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
362	enum Unanswered {
363	    /// The checker decides which props exist, as in the whole-project merge: the structural prop is dropped.
364	    Drop,
365	    /// The checker's props are merged by name, as in a session's merge: the structural prop stays as resolved.
366	    Keep,
367	}
368	
369	fn replace_props<'a>(
370	    entry: &mut ComponentEntry,
371	    props_in: impl Iterator<Item = &'a Arc<SemanticProp>>,
372	    composes: Option<&[String]>,
373	    unanswered: Unanswered,
374	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
375	) -> MergedProps {
376	    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
377	    let mut unread = 0;
378	    for prop in props_in {
379	        let structural = entry.props.get(&prop.name);
380	        let description = if prop.description.is_empty() {
381	            structural.map(|s| s.description.clone()).unwrap_or_default()
382	        } else {
383	            prop.description.clone()
384	        };
385	        let tags = if prop.tags.is_empty() {
386	            structural.map(|s| s.tags.clone()).unwrap_or_default()
387	        } else {
388	            prop.tags.clone()
389	        };
390	        let unread_kinds = structural.map(|s| unread_by_checker(&prop.prop_type, &s.prop_type)).unwrap_or_default();
391	        // The checker sorts a union's members; where the structural pass resolved the same union, its order is the
392	        // declared one.
393	        let prop_type = match structural {
394	            Some(structural) if !unread_kinds.is_empty() => structural.prop_type.clone(),
395	            Some(structural) => order::in_declared_order(prop.prop_type.clone(), &structural.prop_type),
396	            None => prop.prop_type.clone(),
397	        };
398	        unread += usize::from(!unread_kinds.is_empty());
399	        let merged = ParsedProp::new(
400	            prop.name.clone(),
401	            prop_type,
402	            prop.required,
403	            structural.and_then(|s| s.default_value.clone()),
404	            description,
405	            tags,
406	            prop.parent.clone(),
407	            prop.declarations.clone(),
408	        )
409	        .degraded_also_by(&unread_kinds);
410	        let mut hasher = FxHasher::default();
411	        merged.structural_hash(&mut hasher);
412	        let bucket = shared.entry(hasher.finish()).or_default();
413	        let merged = match bucket.iter().find(|existing| ***existing == merged) {
414	            Some(existing) => existing.clone(),
415	            None => {
416	                let merged = Arc::new(merged);
417	                bucket.push(merged.clone());
418	                merged
419	            }
420	        };
421	        props.insert(prop.name.clone(), merged);
422	    }
423	    let mut kept = 0;
424	    if unanswered == Unanswered::Keep {
425	        for (name, structural) in &entry.props {
426	            if !props.contains_key(name) {
427	                props.insert(name.clone(), structural.clone());
428	                kept += 1;
429	            }
430	        }
431	    }
432	    entry.props = props;
433	    if let Some(composes) = composes {
434	        entry.composes = composes.to_vec();
435	    }
436	    MergedProps { kept, unread }
437	}
438	
439	/// Merge the checker's props over `output`, component by component.
440	///
441	/// Per `docs/type-checker-integration.md`: the checker decides which props exist, their types, whether they are
442	/// required, `parent`, `declarations` and the component's `composes`; a description and tags come from the checker,
443	/// else the structural pass; a default value stays structural (the checker has no initializer for a destructured
444	/// parameter), and so does a union's member order where the structural pass resolved the same union (the checker sorts
445	/// members). Inheritance layers, curated inherited props and `discriminantProp` stay structural. Components the checker
446	/// did not answer for keep their structural result untouched.
447	///
448	/// Records provenance as `Info` diagnostics whose `affects` lists the output keys, so the canonical JSON gains no
449	/// field: one for the components the checker resolved, one per fallback reason.
450	pub fn merge_semantic(output: &mut ExtractionOutput, outcome: SemanticOutcome) {
451	    let SemanticOutcome { components, fallbacks, diagnostics } = outcome;
452	    let mut merged_keys = Vec::new();
453	    let (mut unread_keys, mut unread_props) = (Vec::new(), 0);
454	    let mut shared: FxHashMap<u64, Vec<Arc<ParsedProp>>> = FxHashMap::default();
455	    for semantic in components {
456	        let Some(entry) = output.components.get_mut(&semantic.key) else { continue };
457	        let unread = apply_semantic_props(entry, &semantic, &mut shared);
458	        if unread > 0 {
459	            unread_props += unread;
460	            unread_keys.push(semantic.key.clone());
461	        }
462	        merged_keys.push(semantic.key);
463	    }
464	    output.diagnostics.extend(diagnostics);
465	
466	    // A structural diagnostic about a prop the checker now answers for would be stale; the resolved component keeps
467	    // none of its degrade diagnostics.
468	    if !merged_keys.is_empty() {
469	        output.diagnostics.retain(|diagnostic| {
470	            let degrade = matches!(
471	                diagnostic.code,
472	                DiagnosticCode::OpaqueType | DiagnosticCode::MaxDepthExceeded | DiagnosticCode::CircularReference
473	            );
474	            !(degrade
475	                && !diagnostic.affects.is_empty()
476	                && diagnostic.affects.iter().all(|key| merged_keys.contains(key)))
477	        });
478	        merged_keys.sort();
479	        let mut provenance = Diagnostic::new(
480	            DiagnosticSeverity::Info,
481	            DiagnosticCode::SemanticBackend,
482	            format!("{} component(s) resolved by the TypeScript checker", merged_keys.len()),
483	        );
484	        provenance.affects = merged_keys;
485	        output.diagnostics.push(provenance);
486	    }
487	    if !unread_keys.is_empty() {
488	        unread_keys.sort();
489	        output.diagnostics.push(unread_diagnostic(unread_props, unread_keys));
490	    }
491	
492	    let mut by_reason: BTreeMap<String, Vec<String>> = BTreeMap::new();
493	    for SemanticFallback { key, reason } in fallbacks {
494	        if output.components.contains_key(&key) {
495	            by_reason.entry(reason).or_default().push(key);
496	        }
497	    }
498	    for (reason, mut keys) in by_reason {
499	        keys.sort();
500	        let mut diagnostic = Diagnostic::new(
501	            DiagnosticSeverity::Info,
502	            DiagnosticCode::SemanticBackend,
503	            format!("{} component(s) kept their structural result: {reason}", keys.len()),
504	        );
505	        diagnostic.affects = keys;
506	        output.diagnostics.push(diagnostic);
507	    }
508	}
509	
510	#[cfg(test)]
511	mod tests;
