37	/// One prop as the checker reports it.
38	#[derive(Debug, Clone, PartialEq)]
39	pub struct SemanticProp {
40	    /// The prop's name as written in the props type.
41	    pub name: String,
42	    /// The type the checker computed for it, in the same shape the structural resolver produces.
43	    pub prop_type: PropType,
44	    /// Whether the checker found the prop non-optional.
45	    pub required: bool,
46	    /// The prop's JSDoc description, empty when it has none; the merge then keeps the structural description.
47	    pub description: String,
48	    /// The prop's JSDoc tags (`@deprecated`, `@since`, `@default`), each by name with the text the checker renders, empty
49	    /// when it has none; the merge then keeps the structural tags, as for `description`. `@types/react`'s props are not
50	    /// asked for theirs.
51	    pub tags: BTreeMap<String, String>,
52	    /// The interface that declares the prop, as react-docgen-typescript states it: the parent of its first declaration
53	    /// when that is an interface, with the file it is in. `None` for a prop declared in a type literal or with no
54	    /// declaration. It replaces the structural `parent`, `None` included.
55	    pub parent: Option<PropParent>,
56	    /// The interface of each declaration that is in one, in the checker's order: two when an intersection or a merged
57	    /// interface declares the prop twice.
58	    pub declarations: Vec<PropParent>,
59	    /// Declared by `@types/react` (`children`, `aria-*`, handlers, `className`): not the component's own prop.
60	    pub react_declared: bool,
61	}
62	
63	impl SemanticProp {
64	    fn structural_hash(&self) -> u64 {
65	        let mut hasher = FxHasher::default();
66	        self.name.hash(&mut hasher);
67	        self.required.hash(&mut hasher);
68	        self.react_declared.hash(&mut hasher);
69	        self.description.hash(&mut hasher);
70	        self.tags.hash(&mut hasher);
71	        for parent in self.parent.iter().chain(&self.declarations) {
72	            parent.name.hash(&mut hasher);
73	            parent.file_name.hash(&mut hasher);
74	        }
75	        self.prop_type.structural_hash(&mut hasher);
76	        hasher.finish()
77	    }
78	}
