103	/// One component the checker answered for.
104	#[derive(Debug, Clone, PartialEq)]
105	pub struct SemanticComponent {
106	    /// The output key of the [`SemanticTarget`] this answers: the entry to merge into.
107	    pub key: String,
108	    /// Declared props in declaration order, with the `@types/react` ones the request asked for.
109	    pub props: Vec<Arc<SemanticProp>>,
110	    /// The `@types/react` types the props type is made of (`RefAttributes`, `HTMLAttributes` under an `Omit`), by
111	    /// name, in the order the props type names them: what the checker leaves to the inheritance layers. `Some` replaces
112	    /// the structural `composes`, which also lists the types the structural pass could not follow and the checker did,
113	    /// and `Some` of an empty list says the props type is made of none. `None` says the checker could not tell (a type
114	    /// it cannot read the bases of), and the structural `composes` stays.
115	    pub composes: Option<Vec<String>>,
116	}
