118	/// A component the backend left to the structural result, and why.
119	#[derive(Debug, Clone, PartialEq, Eq)]
120	pub struct SemanticFallback {
121	    /// The output key of the [`SemanticTarget`] this answers.
122	    pub key: String,
123	    /// Why the checker did not answer, for example that the component is not exported by its module. The merge groups
124	    /// components by this text into one warning.
