161	/// A checker that answers for components as they are asked about, for a long-lived session.
162	///
163	/// `request` never blocks: it queues the targets and returns the receiver that yields the outcome once the checker
164	/// has it, so a caller can wait a bounded time and take the structural answer when the checker is slower.
165	pub trait SemanticProvider: Send + Sync {
166	    /// Queues `targets` for the checker and returns at once with the receiver that will yield their
167	    /// [`SemanticOutcome`]. Someone is waiting for it: the request is [`Priority::Interactive`].
168	    fn request(&self, targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome>;
169	
170	    /// Queues `targets` at `priority` and returns at once; `delivery` receives the outcome. A checker that answers one
171	    /// request at a time answers an interactive request before a background one, and reads `priority` again when it
172	    /// picks the next, since a caller that joins a background request may raise it. The default ignores the priority
173	    /// and waits for [`Self::request`]'s receiver on a thread of its own.
174	    fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
175	        drop(priority);
176	        let receiver = self.request(targets);
177	        let delivery = Arc::new(Mutex::new(Some(delivery)));
178	        let take =
179	            |slot: &Mutex<Option<Delivery>>| slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
180	        let waiter = delivery.clone();
181	        let waiting = std::thread::Builder::new().name("caliper-checker-answer".to_string()).spawn(move || {
182	            let outcome = receiver.recv().ok();
183	            if let Some(delivery) = take(&waiter) {
184	                delivery.deliver(outcome);
185	            }
186	        });
187	        if let Err(error) = waiting
188	            && let Some(delivery) = take(&delivery)
189	        {
190	            delivery.deliver(Some(SemanticOutcome::unavailable(format!(
191	                "could not start a thread to wait for it: {error}"
192	            ))));
193	        }
194	    }
195	
196	    /// Tells the checker that files changed on disk, before any request that may read them is queued. A checker that
197	    /// keeps what it read (a warm `tsc` holding a snapshot, ADR 0026) reads them again; one that reads every file
198	    /// afresh for each request needs nothing, which is the default.
199	    fn changed(&self, _change: SourceChange) {}
200	}
201	
202	/// Who waits for a request to the checker, which decides what a busy checker answers first.
203	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
204	pub enum Priority {
205	    /// A component someone is looking at now: a story that was opened.
206	    Interactive,
207	    /// Work nobody waits for yet: a warm-up, a fill, a prefetch.
208	    Background,
209	}
210	
211	/// The priority of one queued request, shared between the caller and the checker so that a later caller can raise it
212	/// ([`SharedPriority::raise`]) while the request waits. Clones share one priority.
213	#[derive(Debug, Clone)]
214	pub struct SharedPriority(Arc<std::sync::atomic::AtomicBool>);
215	
216	impl SharedPriority {
217	    /// A priority that starts at `priority`.
218	    pub fn new(priority: Priority) -> Self {
219	        Self(Arc::new(std::sync::atomic::AtomicBool::new(priority == Priority::Interactive)))
220	    }
221	
222	    /// The priority now.
223	    pub fn get(&self) -> Priority {
224	        match self.0.load(std::sync::atomic::Ordering::Acquire) {
225	            true => Priority::Interactive,
226	            false => Priority::Background,
227	        }
228	    }
229	
230	    /// Makes the request interactive: someone is now waiting for it.
231	    pub fn raise(&self) {
232	        self.0.store(true, std::sync::atomic::Ordering::Release);
233	    }
234	}
235	
236	/// Where the outcome of a request made with [`SemanticProvider::request_at`] goes. It is used once: with the outcome,
237	/// or with `None` when the checker stopped without answering. Dropping it unused counts as `None`, so a caller is
238	/// told even when the request is lost (a worker that stopped, a thread that could not start).
239	pub struct Delivery(Option<Box<dyn FnOnce(Option<SemanticOutcome>) + Send>>);
240	
241	impl Delivery {
242	    /// A delivery that hands the outcome to `receive`.
243	    pub fn new(receive: impl FnOnce(Option<SemanticOutcome>) + Send + 'static) -> Self {
244	        Self(Some(Box::new(receive)))
245	    }
246	
247	    /// Hands over the outcome, or `None` for a checker that stopped without answering.
248	    pub fn deliver(mut self, outcome: Option<SemanticOutcome>) {
249	        if let Some(receive) = self.0.take() {
250	            receive(outcome);
251	        }
252	    }
253	}
254	
255	impl Drop for Delivery {
256	    fn drop(&mut self) {
257	        if let Some(receive) = self.0.take() {
258	            receive(None);
259	        }
260	    }
261	}
262	
263	impl std::fmt::Debug for Delivery {
264	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
265	        f.debug_struct("Delivery").field("delivered", &self.0.is_none()).finish()
266	    }
267	}
