1	//! Asking a checker for the component a session was just asked about (ADR 0022).
2	//!
3	//! The structural answer is always computed first and is a complete answer on its own. With a [`SemanticProvider`]
4	//! attached, [`SemanticHook::refine`] asks the checker for exactly that component, waits a bounded time, and merges
5	//! its props over the structural ones. A checker that is slower than the budget leaves the structural answer in
6	//! place, and its late answer is kept for the next request of the same, unedited component.
7	//!
8	//! There is one request in flight per component and version of its file: a caller that finds one waits on it instead
9	//! of asking again, and a caller someone is waiting for raises a background request it joins to interactive, so a
10	//! story asked while its own prefetch runs is answered when the prefetch is.
11	//!
12	//! An answer describes the component's props as the checker read them, which depends on every file the component
13	//! imports, not only its own. So the session drops every answer when any source file changes
14	//! ([`SemanticHook::invalidate`]), and an answer that was still on its way then is neither kept nor joined. The same
15	//! call tells the checker which files changed, since a warm one answers from what it read before (ADR 0026 S6).
16	
17	use std::hash::{Hash, Hasher};
18	use std::sync::atomic::{AtomicBool, Ordering};
19	use std::sync::{Arc, Condvar, Mutex, PoisonError};
20	use std::time::Duration;
21	
22	use rustc_hash::{FxHashMap, FxHasher};
23	
24	use super::ComponentAnswer;
25	use crate::pipeline::HtmlAttributeMode;
26	use crate::react_types::{checker_prop_used, react_props_wanted};
27	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
28	use crate::types::semantic::{
29	    Delivery, MergedProps, Priority, SemanticComponent, SemanticFallback, SemanticOutcome, SemanticProp,
30	    SemanticProvider, SemanticTarget, SharedPriority, SourceChange, merge_semantic_props, unread_diagnostic,
31	};
32	
33	/// What one request of the checker made of a component: the component it found, if any, and what the checker said
34	/// about the request itself (an edit it was not told about, why a component kept its structural result). Both are the
35	/// answer, so a late answer, a joined one and every request the cache serves it to carry both.
36	#[derive(Clone, Default)]
37	struct Answered {
38	    component: Option<Arc<SemanticComponent>>,
39	    diagnostics: Vec<Diagnostic>,
40	}
41	
42	/// What became of one request to the checker, for every caller that waited on it.
43	#[derive(Clone)]
44	enum Settled {
45	    /// The checker answered: what is kept for the component, and what an unavailable checker says once per session.
46	    Answered { answered: Answered, once: Vec<Diagnostic> },
47	    /// The checker stopped without answering.
48	    Stopped,
49	}
50	
51	/// A request in flight. Every caller for the same component and version of its file waits on it instead of asking the
52	/// checker again.
53	struct Pending {
54	    /// What the checker answers it at; a caller someone is waiting for raises it on joining.
55	    priority: SharedPriority,
56	    settled: Mutex<Option<Settled>>,
57	    ready: Condvar,
58	}
59	
60	impl Pending {
61	    fn new(priority: Priority) -> Self {
62	        Self { priority: SharedPriority::new(priority), settled: Mutex::new(None), ready: Condvar::new() }
63	    }
64	
65	    fn settle(&self, settled: Settled) {
66	        *self.settled.lock().unwrap_or_else(PoisonError::into_inner) = Some(settled);
67	        self.ready.notify_all();
68	    }
69	
70	    /// What became of the request, if that is known within `wait`.
71	    fn wait(&self, wait: Duration) -> Option<Settled> {
72	        let settled = self.settled.lock().unwrap_or_else(PoisonError::into_inner);
73	        let (settled, _) = self
74	            .ready
75	            .wait_timeout_while(settled, wait, |settled| settled.is_none())
76	            .unwrap_or_else(PoisonError::into_inner);
77	        settled.clone()
78	    }
79	}
80	
81	/// What the checker said about one component at one version of its file, what it is still being asked, and the
82	/// generation they belong to.
83	#[derive(Default)]
84	struct AnswerCache {
85	    /// Raised by every [`SemanticHook::invalidate`]; an answer asked for under an earlier one is not stored.
86	    generation: u64,
87	    answers: FxHashMap<(String, u64), Answered>,
88	    /// Requests in flight under the current generation, by the same key as `answers`.
89	    pending: FxHashMap<(String, u64), Arc<Pending>>,
90	}
91	
92	type Answers = Mutex<AnswerCache>;
93	
94	/// Where a request finds its answer.
95	enum Found {
96	    /// An answer kept from an earlier request.
97	    Cached(Answered),
98	    /// A request already in flight, to wait on.
99	    Joined(Arc<Pending>),
100	    /// Nothing: this caller asks, and others join it.
101	    Asking(Arc<Pending>),
102	}
103	
104	/// How long a request for a component the structural pass lists no props for waits for the checker, unless the session
105	/// says otherwise ([`SemanticHook::wait_empty`]): an empty answer is not worth showing early, and Chakra's `Button` takes
106	/// 0.4 to 0.8 s.
107	pub(crate) const DEFAULT_WAIT_EMPTY: Duration = Duration::from_secs(2);
108	
109	pub(crate) struct SemanticHook {
110	    provider: Arc<dyn SemanticProvider>,
111	    /// How long a request waits for the checker before it takes the structural answer.
112	    wait: Duration,
113	    /// How long it waits instead when the structural answer has no props; never less than `wait`.
114	    wait_empty: Duration,
115	    answers: Arc<Answers>,
116	    /// Set once the checker has been reported unavailable, so a session says so once, not per component.
117	    warned: AtomicBool,
118	}
119	
120	impl SemanticHook {
121	    pub(crate) fn new(provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
122	        Self {
123	            provider,
124	            wait,
125	            wait_empty: DEFAULT_WAIT_EMPTY,
126	            answers: Arc::new(Mutex::new(AnswerCache::default())),
127	            warned: AtomicBool::new(false),
128	        }
129	    }
130	
131	    /// Sets how long a request for a component with no structural props waits for the checker. A wait at most `wait`
132	    /// gives such a component the same wait as every other.
133	    pub(crate) fn wait_empty(&mut self, wait_empty: Duration) {
134	        self.wait_empty = wait_empty;
135	    }
136	
137	    /// The wait for `answer`. Nobody waits for a background request: its answer is kept for the request that follows.
138	    /// Someone does for an interactive one, and longer when the structural pass found no props, since there is nothing
139	    /// to show before the checker answers. Any prop, even a degraded one, is an answer worth showing at the short wait.
140	    fn wait_for(&self, answer: &ComponentAnswer, priority: Priority) -> Duration {
141	        match (priority, answer.entry.props.is_empty()) {
142	            (Priority::Background, _) => Duration::ZERO,
143	            (Priority::Interactive, true) => self.wait_empty.max(self.wait),
144	            (Priority::Interactive, false) => self.wait,
145	        }
146	    }
147	
148	    /// Forget every answer, refuse the ones still being waited for, and tell the checker what changed: a source file
149	    /// changed, and the checker's props for any component can depend on it. The next request of each component asks
150	    /// the checker again, after it has been told, rather than joining a request asked before the change.
151	    pub(crate) fn invalidate(&self, change: SourceChange) {
152	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
153	        cache.generation += 1;
154	        cache.answers.clear();
155	        cache.pending.clear();
156	        self.provider.changed(change);
157	    }
158	
159	    /// `answer` with the checker's props, when it has them within the wait `priority` gives it.
160	    pub(crate) fn refine(
161	        &self,
162	        mut answer: ComponentAnswer,
163	        mode: HtmlAttributeMode,
164	        priority: Priority,
165	    ) -> ComponentAnswer {
166	        let stamp = std::fs::read(&answer.entry.file_path).map(|bytes| {
167	            let mut hasher = FxHasher::default();
168	            bytes.hash(&mut hasher);
169	            hasher.finish()
170	        });
171	        let cache_key = stamp.ok().map(|stamp| (answer.key.clone(), stamp));
172	
173	        let (found, generation) = self.find(cache_key.as_ref(), priority);
174	        let pending = match found {
175	            Found::Cached(cached) => {
176	                answer.diagnostics.extend(cached.diagnostics);
177	                self.apply(&mut answer, cached.component.as_ref(), mode);
178	                return answer;
179	            }
180	            Found::Joined(pending) => pending,
181	            Found::Asking(pending) => {
182	                self.ask(&answer, mode, &pending, cache_key, generation);
183	                pending
184	            }
185	        };
186	
187	        match pending.wait(self.wait_for(&answer, priority)) {
188	            Some(Settled::Answered { answered, once }) => {
189	                for diagnostic in once {
190	                    if !self.warned.swap(true, Ordering::Relaxed) {
191	                        answer.diagnostics.push(diagnostic);
192	                    }
193	                }
194	                answer.diagnostics.extend(answered.diagnostics);
195	                self.apply(&mut answer, answered.component.as_ref(), mode);
196	            }
197	            Some(Settled::Stopped) => {
198	                let mut stopped = Diagnostic::new(
199	                    DiagnosticSeverity::Warning,
200	                    DiagnosticCode::SemanticBackend,
201	                    "the TypeScript checker stopped without answering; the structural props are used",
202	                );
203	                stopped.affects = vec![answer.key.clone()];
204	                answer.diagnostics.push(stopped);
205	            }
206	            None => {
207	                let mut pending = Diagnostic::new(
208	                    DiagnosticSeverity::Info,
209	                    DiagnosticCode::SemanticBackend,
210	                    "the TypeScript checker has not answered yet; the structural props are used, and the checker's \
211	                     replace them on the next request",
212	                );
213	                pending.affects = vec![answer.key.clone()];
214	                answer.diagnostics.push(pending);
215	            }
216	        }
217	        answer
218	    }
219	
220	    /// The kept answer for `key`, else the request in flight for it (raised when someone waits for this one), else a
221	    /// new request this caller makes, registered so the next caller joins it. One lock, so two callers never both ask.
222	    /// A file that could not be read has no key: its request is neither kept nor joined.
223	    fn find(&self, key: Option<&(String, u64)>, priority: Priority) -> (Found, u64) {
224	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
225	        let generation = cache.generation;
226	        if let Some(key) = key {
227	            if let Some(cached) = cache.answers.get(key) {
228	                return (Found::Cached(cached.clone()), generation);
229	            }
230	            if let Some(pending) = cache.pending.get(key) {
231	                match priority {
232	                    Priority::Interactive => pending.priority.raise(),
233	                    Priority::Background => {}
234	                }
235	                return (Found::Joined(pending.clone()), generation);
236	            }
237	        }
238	        let pending = Arc::new(Pending::new(priority));
239	        if let Some(key) = key {
240	            cache.pending.insert(key.clone(), pending.clone());
241	        }
242	        (Found::Asking(pending), generation)
243	    }
244	
245	    /// Asks the checker for `answer`'s component. Its outcome settles `pending` for every caller waiting on it and is
246	    /// kept for the next request, unless the cache was invalidated since `generation`. Called without the cache's lock,
247	    /// since a provider may deliver at once.
248	    fn ask(
249	        &self,
250	        answer: &ComponentAnswer,
251	        mode: HtmlAttributeMode,
252	        pending: &Arc<Pending>,
253	        key: Option<(String, u64)>,
254	        generation: u64,
255	    ) {
256	        let target = SemanticTarget {
257	            key: answer.key.clone(),
258	            file_path: answer.entry.file_path.clone(),
259	            display_name: answer.entry.display_name.clone(),
260	            exports: answer.entry.exports.clone(),
261	            described: answer
262	                .entry
263	                .props
264	                .values()
265	                .filter(|prop| !prop.description.is_empty())
266	                .map(|prop| prop.name.clone())
267	                .collect(),
268	            react_wanted: react_props_wanted(mode, &answer.entry.props),
269	        };
270	        let answers = self.answers.clone();
271	        let asked = answer.key.clone();
272	        let settling = pending.clone();
273	        let delivery = Delivery::new(move |outcome| {
274	            let settled = match outcome {
275	                Some(outcome) => {
276	                    let Read { answered, once } = read_outcome(&asked, outcome);
277	                    Settled::Answered { answered, once }
278	                }
279	                None => Settled::Stopped,
280	            };
281	            if let Some(key) = key {
282	                let mut cache = answers.lock().unwrap_or_else(PoisonError::into_inner);
283	                if cache.pending.get(&key).is_some_and(|registered| Arc::ptr_eq(registered, &settling)) {
284	                    cache.pending.remove(&key);
285	                }
286	                if let Settled::Answered { answered, .. } = &settled
287	                    && cache.generation == generation
288	                {
289	                    cache.answers.insert(key, answered.clone());
290	                }
291	            }
292	            settling.settle(settled);
293	        });
294	        self.provider.request_at(vec![target], pending.priority.clone(), delivery);
295	    }
296	
297	    fn apply(&self, answer: &mut ComponentAnswer, component: Option<&Arc<SemanticComponent>>, mode: HtmlAttributeMode) {
298	        let Some(component) = component else { return };
299	        let structural = answer.entry.props.clone();
300	        let used: Vec<&Arc<SemanticProp>> = component
301	            .props
302	            .iter()
303	            .filter(|prop| checker_prop_used(mode, &prop.name, prop.react_declared, &structural))
304	            .collect();
305	        // A degrade diagnostic names the component, not the prop, so it can only go once no structural prop is left
306	        // that it could be about: one the checker did not return keeps its structural type, opaque or not.
307	        let still_degraded = structural
308	            .iter()
309	            .any(|(name, prop)| prop.prop_type.holds_opaque() && !used.iter().any(|answered| answered.name == *name));
310	        let MergedProps { kept, unread } = merge_semantic_props(
311	            &mut answer.entry,
312	            used.into_iter(),
313	            component.composes.as_deref(),
314	            &mut FxHashMap::default(),
315	        );
316	        if !still_degraded {
317	            // A structural diagnostic about a prop the checker now answers for would be stale.
318	            answer.diagnostics.retain(|diagnostic| {
319	                !matches!(
320	                    diagnostic.code,
321	                    DiagnosticCode::OpaqueType | DiagnosticCode::MaxDepthExceeded | DiagnosticCode::CircularReference
322	                )
323	            });
324	        }
325	        let mut provenance = Diagnostic::new(
326	            DiagnosticSeverity::Info,
327	            DiagnosticCode::SemanticBackend,
328	            match kept {
329	                0 => "1 component(s) resolved by the TypeScript checker".to_string(),
330	                kept => format!(
331	                    "1 component(s) resolved by the TypeScript checker; {kept} prop(s) it did not report keep their \
332	                     structural type"
333	                ),
334	            },
335	        );
336	        provenance.affects = vec![answer.key.clone()];
337	        answer.diagnostics.push(provenance);
338	        if unread > 0 {
339	            answer.diagnostics.push(unread_diagnostic(unread, vec![answer.key.clone()]));
340	        }
341	    }
342	}
343	
344	/// An outcome read for the component asked about.
345	struct Read {
346	    /// What is kept for the next request: the component and what the checker said about the request, each diagnostic
347	    /// naming the component.
348	    answered: Answered,
349	    /// What an unavailable checker says, which a session says once and not per component, so it is not kept.
350	    once: Vec<Diagnostic>,
351	}
352	
353	/// The answer for the component whose output key is `asked`, and the diagnostics the request produced: a warning that
354	/// came with an answer (an edit the checker was not told about) is about this request, and its fallback's reason says
355	/// why the component kept its structural result. An answer or fallback for another key is not this component's.
356	fn read_outcome(asked: &str, outcome: SemanticOutcome) -> Read {
357	    let SemanticOutcome { components, fallbacks, diagnostics: reported } = outcome;
358	    // Only an outcome with no answer at all says the checker is unavailable.
359	    let unavailable = components.is_empty() && fallbacks.is_empty();
360	    let mut read = Read { answered: Answered::default(), once: Vec::new() };
361	    for mut diagnostic in reported {
362	        diagnostic.affects = vec![asked.to_owned()];
363	        if unavailable && diagnostic.severity == DiagnosticSeverity::Warning {
364	            read.once.push(diagnostic);
365	        } else {
366	            read.answered.diagnostics.push(diagnostic);
367	        }
368	    }
369	    for SemanticFallback { key, reason } in fallbacks {
370	        if key != asked {
371	            continue;
372	        }
373	        let mut info = Diagnostic::new(
374	            DiagnosticSeverity::Info,
375	            DiagnosticCode::SemanticBackend,
376	            format!("1 component(s) kept their structural result: {reason}"),
377	        );
378	        info.affects = vec![key];
379	        read.answered.diagnostics.push(info);
380	    }
381	    read.answered.component = components.into_iter().find(|found| found.key == asked).map(Arc::new);
382	    read
383	}
